import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { ScheduleModule } from '@nestjs/schedule';
import { ServeStaticModule } from '@nestjs/serve-static';
import { join } from 'path';
import { existsSync } from 'fs';
import { TenantModule } from '@mentor-ai/shared/tenant-context';
import { AppController } from './app.controller';
import { AppService } from './app.service';
import { HealthModule } from './health/health.module';
import { RegistrationModule } from './registration/registration.module';
import { AuthModule } from './auth/auth.module';
import { InvitationModule } from './invitation/invitation.module';
import { TeamModule } from './team/team.module';
// DataExportModule and TenantDeletionModule: enable when Redis is available (BullMQ dependency)
import { LlmConfigModule } from './llm-config/llm-config.module';
import { AiGatewayModule } from './ai-gateway/ai-gateway.module';
import { ConversationModule } from './conversation/conversation.module';
import { OnboardingModule } from './onboarding/onboarding.module';
import { PersonasModule } from './personas/personas.module';
import { KnowledgeModule } from './knowledge/knowledge.module';
import { MemoryModule } from './memory/memory.module';
import { QdrantModule } from './qdrant/qdrant.module';
import { WebSearchModule } from './web-search/web-search.module';
import { AdminModule } from './admin/admin.module';
import { ExecutionModule } from './execution/execution.module';
import { AttachmentsModule } from './attachments/attachments.module';
import { PdfExportModule } from './pdf-export/pdf-export.module';
import { AgentExecutionModule } from './agent-execution/agent-execution.module';
import { MaturityModule } from './maturity/maturity.module';

// Serve Angular static files in production (combined deploy)
const staticPath = join(__dirname, '..', '..', 'web', 'browser');
const serveStaticImports = existsSync(staticPath)
  ? [
      ServeStaticModule.forRoot({
        rootPath: staticPath,
        exclude: ['/api{/*path}', '/ws{/*path}'],
      }),
    ]
  : [];

@Module({
  imports: [
    ConfigModule.forRoot({
      isGlobal: true,
      envFilePath: ['apps/api/.env.local', 'apps/api/.env', '.env.local', '.env'],
    }),
    ScheduleModule.forRoot(),
    ...serveStaticImports,
    QdrantModule,
    TenantModule,
    HealthModule,
    RegistrationModule,
    AuthModule,
    InvitationModule,
    TeamModule,
    // TODO: Enable when Redis is available (BullMQ dependency)
    // DataExportModule,
    // TenantDeletionModule,
    LlmConfigModule,
    AiGatewayModule,
    ConversationModule,
    OnboardingModule,
    PersonasModule,
    KnowledgeModule,
    MemoryModule,
    WebSearchModule,
    AdminModule,
    ExecutionModule,
    AttachmentsModule,
    PdfExportModule,
    AgentExecutionModule,
    MaturityModule,
  ],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {}
